@@ -0,0 +1,71 @@
+package tests
+
+import (
+	"errors"
+	"reflect"
+	"testing"
+
+	"example.com/bank/account"
+	"example.com/bank/ledger"
+)
+
+func TestTransferMovesFundsAndRecordsHistory(t *testing.T) {
+	l := ledger.New()
+	a := account.New("a", "al", 1000)
+	b := account.New("b", "bo", 200)
+	_ = l.Open(a)
+	_ = l.Open(b)
+	if err := l.Transfer("a", "b", 300, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	if a.Balance != 700 || b.Balance != 500 {
+		t.Fatalf("balances = %d, %d; want 700, 500", a.Balance, b.Balance)
+	}
+	if !reflect.DeepEqual(a.History, []account.Entry{
+		{Kind: "transfer-out", Amount: -300, Memo: "rent", BalanceAfter: 700, Counterparty: "b"},
+	}) {
+		t.Fatalf("a.History = %+v", a.History)
+	}
+	if !reflect.DeepEqual(b.History, []account.Entry{
+		{Kind: "transfer-in", Amount: 300, Memo: "rent", BalanceAfter: 500, Counterparty: "a"},
+	}) {
+		t.Fatalf("b.History = %+v", b.History)
+	}
+}
+
+func TestTransferErrorsAreAtomicAndOrdered(t *testing.T) {
+	l := ledger.New()
+	a := account.New("a", "al", 100)
+	a.OverdraftLimit = 50
+	b := account.New("b", "bo", 0)
+	_ = l.Open(a)
+	_ = l.Open(b)
+
+	cases := []struct {
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"a", "b", 0, ledger.ErrInvalidAmount},
+		{"a", "a", 10, ledger.ErrSameAccount},
+		{"zz", "zz", 10, ledger.ErrSameAccount},
+		{"a", "zz", 10, ledger.ErrUnknownAccount},
+		{"zz", "b", 10, ledger.ErrUnknownAccount},
+		{"a", "b", 151, ledger.ErrInsufficientFunds},
+	}
+	for _, c := range cases {
+		if err := l.Transfer(c.from, c.to, c.cents, ""); !errors.Is(err, c.want) {
+			t.Fatalf("Transfer(%s,%s,%d) err = %v, want %v", c.from, c.to, c.cents, err, c.want)
+		}
+	}
+	if a.Balance != 100 || b.Balance != 0 || len(a.History) != 0 || len(b.History) != 0 {
+		t.Fatalf("failed transfers changed state: a=%+v b=%+v", a, b)
+	}
+	// Exactly -OverdraftLimit is allowed.
+	if err := l.Transfer("a", "b", 150, ""); err != nil {
+		t.Fatalf("transfer to exactly -50: %v", err)
+	}
+	if a.Balance != -50 || b.Balance != 150 {
+		t.Fatalf("balances = %d, %d", a.Balance, b.Balance)
+	}
+}

