@@ -0,0 +1,96 @@
+package tests
+
+import (
+	"errors"
+	"math"
+	"testing"
+	"time"
+
+	"example.com/ratelimit/ratelimit"
+)
+
+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct {
+		capacity, refill float64
+		now              func() time.Time
+	}{
+		{0, 1, c.Now},
+		{-1, 1, c.Now},
+		{math.NaN(), 1, c.Now},
+		{math.Inf(1), 1, c.Now},
+		{1, 0, c.Now},
+		{1, math.Inf(1), c.Now},
+		{1, math.NaN(), c.Now},
+		{1, 1, nil},
+	}
+	for i, tc := range bad {
+		b, err := ratelimit.NewBucket(tc.capacity, tc.refill, tc.now)
+		if b != nil || !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("case %d: got (%v, %v), want (nil, ErrInvalidConfig)", i, b, err)
+		}
+	}
+}
+
+func TestBucketStartsFullAndRefills(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(2) {
+		t.Fatal("full bucket should allow 2 tokens")
+	}
+	if b.Allow(1) {
+		t.Fatal("empty bucket should refuse 1 token")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+	c.Advance(10 * time.Second)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want capacity 2", got)
+	}
+}
+
+func TestBucketAllowIsAllOrNothing(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(3, 1, c.Now)
+	if !b.Allow(2) {
+		t.Fatal("Allow(2) on full bucket should succeed")
+	}
+	if b.Allow(2) {
+		t.Fatal("Allow(2) with 1 token left should fail")
+	}
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("failed Allow must take nothing, Tokens() = %v, want 1", got)
+	}
+}
+
+func TestBucketRejectsInvalidAmounts(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(3, 1, c.Now)
+	for _, n := range []float64{0, -1, math.NaN(), 4, math.Inf(1)} {
+		if b.Allow(n) {
+			t.Fatalf("Allow(%v) should be false", n)
+		}
+	}
+	if got := b.Tokens(); got != 3 {
+		t.Fatalf("rejected Allow must take nothing, Tokens() = %v, want 3", got)
+	}
+}
+
+func TestBucketClockGoingBackwardsDoesNotRefill(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(4, 1, c.Now)
+	b.Allow(4)
+	c.Advance(-time.Second)
+	if got := b.Tokens(); got != 0 {
+		t.Fatalf("Tokens() after clock went back = %v, want 0", got)
+	}
+	c.Advance(2 * time.Second) // back to the original reference time + 1s
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens() = %v, want 1 (refill resumes past latest seen time)", got)
+	}
+}

