+package tests
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"testing"
+	"time"
+
+	"example.com/sched/sched"
+)
+
+func TestPlanBatchesDedupe(t *testing.T) {
+	got, err := sched.Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"doc":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"doc", "util"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanUnknownDep(t *testing.T) {
+	_, err := sched.Plan(map[string][]string{"b": {"zz", "a"}, "a": {"c"}, "c": nil})
+	var ud *sched.UnknownDepError
+	if !errors.As(err, &ud) || ud.Task != "b" || ud.Dep != "zz" {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestPlanCycleCanonicalPathSkipsShortcut(t *testing.T) {
+	_, err := sched.Plan(map[string][]string{
+		"p": {"r", "q"},
+		"q": {"s"},
+		"s": {"p"},
+		"r": {"p"},
+	})
+	var ce *sched.CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	want := []string{"p", "q", "s", "p"}
+	if !reflect.DeepEqual(ce.Path, want) {
+		t.Fatalf("Path = %v, want %v", ce.Path, want)
+	}
+	if ce.Error() != "dependency cycle: p -> q -> s -> p" {
+		t.Fatalf("Error = %q", ce.Error())
+	}
+}
+
+func TestSimulateSmall(t *testing.T) {
+	s, err := sched.Simulate(map[string]sched.Task{
+		"a": {Duration: 3},
+		"b": {Deps: []string{"a"}, Duration: 2},
+		"c": {Duration: 4},
+	}, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Makespan != 5 {
+		t.Fatalf("Makespan = %d, want 5", s.Makespan)
+	}
+	if s.Slots["a"] != (sched.Slot{Start: 0, End: 3, Worker: 1}) {
+		t.Fatalf("a = %+v", s.Slots["a"])
+	}
+	if s.Slots["c"] != (sched.Slot{Start: 0, End: 4, Worker: 0}) {
+		t.Fatalf("c = %+v", s.Slots["c"])
+	}
+	if !reflect.DeepEqual(s.CriticalPath, []string{"a", "b"}) {
+		t.Fatalf("CriticalPath = %v", s.CriticalPath)
+	}
+}
+
+func TestSimulateErrors(t *testing.T) {
+	if _, err := sched.Simulate(nil, 0); !errors.Is(err, sched.ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err := sched.Simulate(map[string]sched.Task{"x": {Duration: 0}, "w": {Duration: -1}}, 1)
+	var id *sched.InvalidDurationError
+	if !errors.As(err, &id) || id.Task != "w" {
+		t.Fatalf("err = %v", err)
+	}
+	s, err := sched.Simulate(nil, 3)
+	if err != nil || s.Slots == nil || len(s.Slots) != 0 || s.CriticalPath == nil || s.Makespan != 0 {
+		t.Fatalf("empty = %+v, %v", s, err)
+	}
+}
+
+func TestLargeGraphsWithinLimit(t *testing.T) {
+	const n = 200000
+	tasks := make(map[string][]string, n)
+	deps := make(map[string]sched.Task, n)
+	name := func(i int) string { return fmt.Sprintf("t%06d", i) }
+	for i := 0; i < n; i++ {
+		var d []string
+		if i > 0 {
+			d = append(d, name(i-1))
+		}
+		if i > 1 {
+			d = append(d, name(i/2))
+		}
+		tasks[name(i)] = d
+		deps[name(i)] = sched.Task{Deps: d, Duration: 1 + i%7, Priority: i % 3}
+	}
+	start := time.Now()
+	if _, err := sched.Plan(tasks); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := sched.Simulate(deps, 8); err != nil {
+		t.Fatal(err)
+	}
+	if el := time.Since(start); el > 2*time.Second {
+		t.Fatalf("took %v", el)
+	}
+}
+
+func TestLargeRingCycleWithinLimit(t *testing.T) {
+	const ring = 100000
+	tasks := make(map[string][]string, 200000)
+	name := func(i int) string { return fmt.Sprintf("r%06d", i) }
+	for i := 0; i < ring; i++ {
+		tasks[name(i)] = []string{name((i + 1) % ring)}
+	}
+	for i := 0; i < 100000; i++ {
+		tasks[fmt.Sprintf("c%06d", i)] = []string{fmt.Sprintf("c%06d", i+1)}
+	}
+	tasks[fmt.Sprintf("c%06d", 100000)] = []string{name(0)}
+	start := time.Now()
+	_, err := sched.Plan(tasks)
+	var ce *sched.CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	if el := time.Since(start); el > 2*time.Second {
+		t.Fatalf("took %v", el)
+	}
+}

