diff --git a/tests/loki_wall_intervals.rs b/tests/loki_wall_intervals.rs
new file mode 100644
index 0000000..5765566
--- /dev/null
+++ b/tests/loki_wall_intervals.rs
@@ -0,0 +1,177 @@
+use intervalkit::intervals::{Bound, IntervalSet};
+use std::time::Instant;
+
+use Bound::{Closed as C, Open as O};
+
+#[test]
+fn empty_intervals_are_ignored_but_closed_point_is_not_empty() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(2));
+    s.insert(C(2), O(2));
+    s.insert(O(2), C(2));
+    s.insert(C(3), C(2));
+    assert!(s.is_empty());
+    assert_eq!(s.ranges(), Vec::<(Bound, Bound)>::new());
+    assert_eq!(s.measure(), 0);
+    s.insert(C(2), C(2));
+    assert!(!s.is_empty());
+    assert_eq!(s.ranges(), vec![(C(2), C(2))]);
+}
+
+#[test]
+fn open_interval_on_real_line_is_nonempty() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(3));
+    assert!(!s.is_empty());
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+    assert_eq!(s.ranges(), vec![(O(2), O(3))]);
+    assert_eq!(s.measure(), 1);
+}
+
+#[test]
+fn single_point_has_zero_measure_and_excludes_neighbours() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), C(2));
+    assert_eq!(s.ranges(), vec![(C(2), C(2))]);
+    assert!(s.contains(2.0));
+    assert!(!s.contains(2.5));
+    assert_eq!(s.measure(), 0);
+}
+
+#[test]
+fn intervals_merge_only_when_union_is_one_interval() {
+    let mut a = IntervalSet::new();
+    a.insert(C(1), O(3));
+    a.insert(C(3), C(5));
+    assert_eq!(a.ranges(), vec![(C(1), C(5))]);
+
+    let mut b = IntervalSet::new();
+    b.insert(C(1), C(3));
+    b.insert(O(3), O(5));
+    assert_eq!(b.ranges(), vec![(C(1), O(5))]);
+
+    let mut c = IntervalSet::new();
+    c.insert(O(1), O(3));
+    c.insert(C(3), C(3));
+    assert_eq!(c.ranges(), vec![(O(1), C(3))]);
+
+    let mut d = IntervalSet::new();
+    d.insert(O(1), O(3));
+    d.insert(O(3), O(5));
+    assert_eq!(d.ranges(), vec![(O(1), O(3)), (O(3), O(5))]);
+
+    let mut e = IntervalSet::new();
+    e.insert(C(1), O(3));
+    e.insert(O(3), C(5));
+    assert_eq!(e.ranges(), vec![(C(1), O(3)), (O(3), C(5))]);
+}
+
+#[test]
+fn remove_splits_stored_interval() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(C(2), C(2));
+    assert_eq!(s.ranges(), vec![(C(1), O(2)), (O(2), C(5))]);
+    assert!(!s.contains(2.0));
+    assert!(s.contains(1.5));
+
+    let mut t = IntervalSet::new();
+    t.insert(C(1), C(5));
+    t.remove(O(2), O(4));
+    assert_eq!(t.ranges(), vec![(C(1), C(2)), (C(4), C(5))]);
+    assert!(t.contains(2.0));
+    assert!(!t.contains(3.0));
+    assert!(t.contains(4.0));
+}
+
+#[test]
+fn remove_ignores_empty_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(C(3), C(2));
+    s.remove(O(3), O(3));
+    assert_eq!(s.ranges(), vec![(C(1), C(5))]);
+}
+
+#[test]
+fn complement_flips_endpoints_at_window_boundaries() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), O(4));
+    s.insert(O(6), C(8));
+    assert_eq!(
+        s.complement(C(0), C(10)),
+        vec![(C(0), O(2)), (C(4), C(6)), (O(8), C(10))]
+    );
+    assert_eq!(s.complement(C(0), C(1)), vec![(C(0), C(1))]);
+    assert_eq!(s.complement(C(2), O(4)), Vec::<(Bound, Bound)>::new());
+    assert_eq!(s.complement(C(3), O(3)), Vec::<(Bound, Bound)>::new());
+}
+
+#[test]
+fn display_uses_canonical_form() {
+    let mut s = IntervalSet::new();
+    s.insert(C(7), C(7));
+    s.insert(O(4), C(5));
+    s.insert(C(1), O(3));
+    assert_eq!(s.to_string(), "{[1,3), (4,5], [7,7]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(O(-3), C(0));
+    assert_eq!(t.to_string(), "{(-3,0]}");
+
+    assert_eq!(IntervalSet::new().to_string(), "{}");
+    t.insert(C(0), C(0));
+    assert_ne!(t.to_string(), "{}");
+}
+
+#[test]
+fn extreme_i64_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    assert_eq!(s.measure(), (i64::MAX as i128) - (i64::MIN as i128));
+    assert!(s.contains(0.0));
+    assert!(s.contains(i64::MIN as f64));
+
+    let mut t = IntervalSet::new();
+    t.insert(O(i64::MIN), O(i64::MAX));
+    assert!(!t.contains(i64::MIN as f64));
+    assert_eq!(t.measure(), (i64::MAX as i128) - (i64::MIN as i128));
+
+    s.remove(C(i64::MIN), C(0));
+    assert_eq!(s.ranges(), vec![(O(0), C(i64::MAX))]);
+    assert_eq!(
+        IntervalSet::new().complement(C(i64::MIN), C(i64::MAX)),
+        vec![(C(i64::MIN), C(i64::MAX))]
+    );
+}
+
+#[test]
+fn many_inserts_and_removes_stay_fast() {
+    let mut s = IntervalSet::new();
+    let mut state: u64 = 0x2545_F491_4F6C_DD1D;
+    let mut next = move || {
+        state = state
+            .wrapping_mul(6364136223846793005)
+            .wrapping_add(1442695040888963407);
+        state >> 33
+    };
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let jitter = (next() % 2001) as i64 - 1000;
+        let lo = 1_000_000_000 - i * 3000 + jitter;
+        let hi = lo + (next() % 1001) as i64;
+        s.insert(C(lo), C(hi));
+
+        let rlo = (next() % 1_000_000_001) as i64;
+        let rhi = rlo + (next() % 1001) as i64;
+        s.remove(C(rlo), C(rhi));
+
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    let elapsed = start.elapsed().as_secs_f64();
+    assert!(!s.is_empty());
+    assert!(elapsed < 3.0, "workload took {elapsed:.3}s, limit is 3s");
+}

