+use romankit::{from_roman, to_roman, RomanError};
+
+#[test]
+fn from_roman_reads_subtractive_numerals() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert_ne!(from_roman("IV").ok(), Some(6));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM", "VV", "LL", "DD", "XXXX"] {
+        assert!(
+            matches!(from_roman(s), Err(RomanError::NonCanonical)),
+            "expected NonCanonical for {s:?}"
+        );
+    }
+    assert!(!matches!(from_roman("MMMM"), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_character() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("X IV"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IVxq"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IVqx"), Err(RomanError::InvalidChar('q'))));
+}
+
+#[test]
+fn to_roman_rejects_out_of_range_values() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(to_roman(0).ok().map_or(true, |s| s != ""));
+}
+
+#[test]
+fn to_roman_produces_canonical_numerals_at_bounds() {
+    assert_eq!(to_roman(1).ok(), Some("I".to_string()));
+    assert_eq!(to_roman(4).ok(), Some("IV".to_string()));
+    assert_eq!(to_roman(3999).ok(), Some("MMMCMXCIX".to_string()));
+    assert_ne!(to_roman(4).ok(), Some("IIII".to_string()));
+}
+
+#[test]
+fn from_roman_inverts_to_roman_across_full_range() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).ok();
+        assert!(s.is_some(), "to_roman({n}) should be Ok");
+        let s = s.unwrap_or_default();
+        assert_eq!(from_roman(&s).ok(), Some(n), "round trip failed for {n} ({s})");
+    }
+}
