+use std::f64::consts::PI;
+
+use shapekit::{Shape, ShapeError};
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn parse_maps_kinds_case_insensitively() {
+    assert_eq!(Shape::parse("circle", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(Shape::parse("CiRcLe", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(Shape::parse("rect", &[3.0, 4.0]), Ok(Shape::Rect { w: 3.0, h: 4.0 }));
+    assert_eq!(Shape::parse("Rectangle", &[3.0, 4.0]), Ok(Shape::Rect { w: 3.0, h: 4.0 }));
+    assert_eq!(Shape::parse("SQUARE", &[5.0]), Ok(Shape::Rect { w: 5.0, h: 5.0 }));
+    assert_eq!(Shape::parse("Triangle", &[3.0, 4.0, 5.0]), Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }));
+    assert_eq!(Shape::parse("hexagon", &[1.0]), Err(ShapeError::UnknownKind("hexagon".to_string())));
+}
+
+#[test]
+fn parse_reports_unknown_kind_with_original_casing() {
+    let err = Shape::parse("HeXagon", &[1.0]).unwrap_err();
+    assert_eq!(err, ShapeError::UnknownKind("HeXagon".to_string()));
+    assert_eq!(err.to_string(), "unknown shape kind: HeXagon");
+}
+
+#[test]
+fn parse_rejects_wrong_param_count() {
+    assert_eq!(
+        Shape::parse("circle", &[1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(
+        Shape::parse("rect", &[1.0]),
+        Err(ShapeError::WrongParamCount { expected: 2, got: 1 })
+    );
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 2, got: 1 }.to_string(),
+        "expected 2 params, got 1"
+    );
+}
+
+#[test]
+fn parse_checks_unknown_kind_before_count_and_count_before_sign() {
+    assert_eq!(
+        Shape::parse("hexagon", &[-1.0]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+    assert_eq!(
+        Shape::parse("circle", &[-1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+}
+
+#[test]
+fn parse_rejects_negative_params_and_bad_triangles() {
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        ShapeError::NegativeDimension.to_string(),
+        "dimensions must be non-negative"
+    );
+    assert_eq!(Shape::parse("triangle", &[1.0, 1.0, 3.0]), Err(ShapeError::InvalidTriangle));
+    assert_eq!(
+        ShapeError::InvalidTriangle.to_string(),
+        "sides do not form a triangle"
+    );
+}
+
+#[test]
+fn degenerate_and_zero_dimensions_are_valid() {
+    let tri = Shape::parse("triangle", &[1.0, 2.0, 3.0]).unwrap();
+    assert!(close(tri.area().unwrap(), 0.0));
+    assert!(close(tri.perimeter().unwrap(), 6.0));
+    assert_eq!(Shape::Rect { w: 0.0, h: 0.0 }.area(), Ok(0.0));
+    assert_eq!(Shape::Rect { w: 0.0, h: 0.0 }.perimeter(), Ok(0.0));
+    assert_eq!(Shape::Circle { r: 0.0 }.area(), Ok(0.0));
+}
+
+#[test]
+fn method_area_and_perimeter_compute_values() {
+    assert!(close(Shape::Circle { r: 2.0 }.area().unwrap(), 4.0 * PI));
+    assert!(close(Shape::Circle { r: 2.0 }.perimeter().unwrap(), 4.0 * PI));
+    assert!(close(Shape::Rect { w: 3.0, h: 4.0 }.area().unwrap(), 12.0));
+    assert!(close(Shape::Rect { w: 3.0, h: 4.0 }.perimeter().unwrap(), 14.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.area().unwrap(), 6.0));
+    assert!(close(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 }.perimeter().unwrap(), 12.0));
+}
+
+#[test]
+fn method_validation_orders_negative_before_triangle() {
+    assert_eq!(Shape::Circle { r: -1.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: 1.0, h: -1.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        Shape::Triangle { a: -1.0, b: 1.0, c: 1.0 }.area(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Triangle { a: -1.0, b: 1.0, c: 1.0 }.perimeter(),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 5.0 }.area(),
+        Err(ShapeError::InvalidTriangle)
+    );
+    assert_eq!(
+        Shape::Triangle { a: 1.0, b: 1.0, c: 5.0 }.perimeter(),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn free_area_function_wraps_shape_and_keeps_messages() {
+    let circle = shapekit::area::area("circle", &[1.0]).unwrap();
+    assert!(close(circle, PI));
+    assert_eq!(
+        shapekit::area::area("hexagon", &[]),
+        Err("unknown shape kind: hexagon".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("rect", &[1.0]),
+        Err("expected 2 params, got 1".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("circle", &[-1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(
+        shapekit::area::area("triangle", &[1.0, 1.0, 5.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+    assert!(close(shapekit::area::area("triangle", &[1.0, 2.0, 3.0]).unwrap(), 0.0));
+}
+
+#[test]
+fn free_perimeter_function_wraps_shape_and_keeps_messages() {
+    assert!(close(shapekit::perimeter::perimeter("square", &[2.0]).unwrap(), 8.0));
+    assert!(close(shapekit::perimeter::perimeter("triangle", &[3.0, 4.0, 5.0]).unwrap(), 12.0));
+    assert_eq!(
+        shapekit::perimeter::perimeter("hexagon", &[1.0]),
+        Err("unknown shape kind: hexagon".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("circle", &[1.0, 2.0]),
+        Err("expected 1 params, got 2".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("rect", &[-1.0, 2.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("triangle", &[1.0, 1.0, 5.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+}

