+use statkit::report::summary;
+use statkit::stats::{count, mean, median, percentile};
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_matches_expected_report() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_empty_or_all_nan_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, f64::NAN, 2.0, 3.0, 4.0]), "n=5 mean=NaN p50=2.50 p90=3.70");
+}
+
+#[test]
+fn count_ignores_nan() {
+    assert!(close(count(&[1.0, f64::NAN, 3.0]) as f64, 2.0));
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+    assert_eq!(count(&[]), 0);
+    assert_eq!(count(&[f64::NAN]), 0);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_empty() {
+    assert!(close(mean(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(mean(&[1.0, f64::NAN, 3.0]).unwrap(), 2.0));
+    assert!(mean(&[1.0, f64::NAN, 3.0]).unwrap().is_finite());
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN]), None);
+}
+
+#[test]
+fn median_is_percentile_50_ignoring_nan() {
+    assert!(close(median(&[3.0, 1.0, 2.0]).unwrap(), 2.0));
+    assert!(close(median(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(median(&[f64::NAN, 5.0]).unwrap(), 5.0));
+    assert_ne!(median(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 3.0);
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+}
+
+#[test]
+fn percentile_endpoints_are_min_and_max() {
+    let v = [4.0, 1.0, 3.0, 2.0];
+    assert!(close(percentile(&v, 0.0).unwrap(), 1.0));
+    assert!(close(percentile(&v, 100.0).unwrap(), 4.0));
+    assert_ne!(percentile(&v, 0.0).unwrap(), 4.0);
+}
+
+#[test]
+fn percentile_uses_linear_interpolation() {
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0).unwrap(), 3.7));
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 50.0).unwrap(), 2.5));
+    assert!(close(percentile(&[7.0], 50.0).unwrap(), 7.0));
+    assert_ne!(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0).unwrap(), 3.0);
+}
+
+#[test]
+fn percentile_is_order_independent_and_does_not_mutate_input() {
+    let v = [4.0, 1.0, 3.0, 2.0];
+    assert!(close(percentile(&v, 90.0).unwrap(), 3.7));
+    assert_eq!(v, [4.0, 1.0, 3.0, 2.0]);
+}
+
+#[test]
+fn percentile_ignores_nan() {
+    assert!(close(percentile(&[f64::NAN, 1.0, 2.0, 3.0, 4.0], 90.0).unwrap(), 3.7));
+    assert_eq!(percentile(&[f64::NAN], 50.0), None);
+    assert_eq!(percentile(&[], 50.0), None);
+}
+
+#[test]
+fn percentile_rejects_invalid_p() {
+    let v = [1.0, 2.0, 3.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -1.0), None);
+    assert_eq!(percentile(&v, 100.5), None);
+    assert!(percentile(&v, 100.0).is_some());
+}
