+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_of_four_values() {
+    assert_eq!(
+        summary(&[1.0, 2.0, 3.0, 4.0]),
+        "n=4 mean=2.50 p50=2.50 p90=3.70"
+    );
+}
+
+#[test]
+fn summary_is_order_independent() {
+    assert_eq!(
+        summary(&[4.0, 1.0, 3.0, 2.0]),
+        "n=4 mean=2.50 p50=2.50 p90=3.70"
+    );
+}
+
+#[test]
+fn summary_of_empty_and_all_nan_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+}
+
+#[test]
+fn nan_values_are_ignored() {
+    let v = [1.0, f64::NAN, 3.0];
+    assert_eq!(count(&v), 2);
+    assert!(close(mean(&v).unwrap(), 2.0));
+    assert!(close(median(&v).unwrap(), 2.0));
+}
+
+#[test]
+fn undefined_statistics_are_none() {
+    assert_eq!(mean(&[]), None);
+    assert_eq!(median(&[]), None);
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(mean(&[f64::NAN]), None);
+}
+
+#[test]
+fn invalid_p_is_none() {
+    let v = [1.0, 2.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+}
+
+#[test]
+fn percentile_does_not_mutate_input() {
+    let v = [3.0, 1.0, 2.0];
+    let _ = percentile(&v, 50.0);
