+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("plum", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 10);
+}
+
+#[test]
+fn reserve_is_all_or_nothing() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let order = Order::new("o").with_line("apple", 2).with_line("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+}
+
+#[test]
+fn reserve_reports_insufficient_with_summed_quantity() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let order = Order::new("o").with_line("apple", 3).with_line("apple", 3);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "apple".to_string(),
+            requested: 6,
+            available: 5,
+        })
+    );
+    assert_eq!(inv.available("apple"), 5);
+}
+
+#[test]
+fn commit_drops_on_hand_and_keeps_available() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 6);
+    assert_eq!(inv.available("apple"), before);
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn ids_are_not_reused_and_unknown_ids_fail() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let a = inv.reserve(&Order::new("a").with_line("apple", 1)).unwrap();
+    inv.release(a).unwrap();
+    let b = inv.reserve(&Order::new("b").with_line("apple", 1)).unwrap();
+    assert_ne!(a, b);
+    assert!(inv.release(a).is_err());
+}
+
+#[test]
+fn empty_order_reserves_nothing() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 0)).unwrap();
+    assert_eq!(inv.available("apple"), 1);
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 1);
+}

