+package tests
+
+import (
+	"errors"
+	"reflect"
+	"testing"
+
+	"example.com/bank/account"
+	"example.com/bank/ledger"
+)
+
+func newTransferLedger(t *testing.T) *ledger.Ledger {
+	t.Helper()
+	l := ledger.New()
+	a := account.New("a", "al", 1000)
+	a.OverdraftLimit = 100
+	b := account.New("b", "bo", 50)
+	for _, acc := range []*account.Account{a, b} {
+		if err := l.Open(acc); err != nil {
+			t.Fatal(err)
+		}
+	}
+	return l
+}
+
+func TestTransferMovesMoneyAndRecordsHistory(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 300, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	a, _ := l.Get("a")
+	b, _ := l.Get("b")
+	if a.Balance != 700 || b.Balance != 350 {
+		t.Fatalf("balances = %d, %d; want 700, 350", a.Balance, b.Balance)
+	}
+	if want := []account.Entry{{Kind: "transfer-out", Amount: -300, Memo: "rent", BalanceAfter: 700, Counterparty: "b"}}; !reflect.DeepEqual(a.History, want) {
+		t.Fatalf("source History = %+v, want %+v", a.History, want)
+	}
+	if want := []account.Entry{{Kind: "transfer-in", Amount: 300, Memo: "rent", BalanceAfter: 350, Counterparty: "a"}}; !reflect.DeepEqual(b.History, want) {
+		t.Fatalf("destination History = %+v, want %+v", b.History, want)
+	}
+	if l.Total() != 1050 {
+		t.Fatalf("Total = %d, want 1050", l.Total())
+	}
+}
+
+func TestTransferAllowsExactOverdraftLimit(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 1100, ""); err != nil {
+		t.Fatalf("transfer to exactly -100: %v", err)
+	}
+	a, _ := l.Get("a")
+	if a.Balance != -100 {
+		t.Fatalf("Balance = %d, want -100", a.Balance)
+	}
+}
+
+func TestTransferErrorsAreAtomicAndOrdered(t *testing.T) {
+	cases := []struct {
+		name     string
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"zero amount", "a", "b", 0, ledger.ErrInvalidAmount},
+		{"negative amount", "a", "b", -5, ledger.ErrInvalidAmount},
+		{"same account", "a", "a", 10, ledger.ErrSameAccount},
+		{"same unknown id", "zz", "zz", 10, ledger.ErrSameAccount},
+		{"unknown source", "zz", "b", 10, ledger.ErrUnknownAccount},
+		{"unknown destination", "a", "zz", 10, ledger.ErrUnknownAccount},
+		{"insufficient funds", "a", "b", 1101, ledger.ErrInsufficientFunds},
+		{"invalid amount beats unknown id", "zz", "b", 0, ledger.ErrInvalidAmount},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			l := newTransferLedger(t)
+			err := l.Transfer(c.from, c.to, c.cents, "x")
+			if !errors.Is(err, c.want) {
+				t.Fatalf("err = %v, want %v", err, c.want)
+			}
+			a, _ := l.Get("a")
+			b, _ := l.Get("b")
+			if a.Balance != 1000 || b.Balance != 50 || len(a.History) != 0 || len(b.History) != 0 {
+				t.Fatalf("state changed after failed transfer: a=%+v b=%+v", a, b)
+			}
+		})
+	}
+}
+
+func TestDepositHasNoCounterparty(t *testing.T) {
+	a := account.New("a", "al", 0)
+	if err := a.Deposit(10, "pay"); err != nil {
+		t.Fatal(err)
+	}
+	if a.History[0].Counterparty != "" {
+		t.Fatalf("Counterparty = %q, want empty", a.History[0].Counterparty)
+	}
+}

