@@ -0,0 +1,61 @@
+package ratelimit
+
+import (
+	"math"
+	"testing"
+	"time"
+)
+
+func TestBucketRefillsAndCaps(t *testing.T) {
+	cur := time.Unix(0, 0)
+	now := func() time.Time { return cur }
+	b, err := NewBucket(2, 2, now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(2) || b.Allow(0.5) {
+		t.Fatal("bucket should start full and then be empty")
+	}
+	cur = cur.Add(250 * time.Millisecond)
+	if got := b.Tokens(); math.Abs(got-0.5) > 1e-9 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+	cur = cur.Add(time.Hour)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want capacity 2", got)
+	}
+	if b.Allow(3) {
+		t.Fatal("n greater than capacity must be rejected")
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	cur := time.Unix(100, 0)
+	now := func() time.Time { return cur }
+	b, _ := NewBucket(1, 1, now)
+	b.Allow(1)
+	cur = cur.Add(-time.Second)
+	if got := b.Tokens(); got != 0 {
+		t.Fatalf("Tokens() = %v after clock went back, want 0", got)
+	}
+	cur = time.Unix(100, 0).Add(500 * time.Millisecond)
+	if got := b.Tokens(); math.Abs(got-0.5) > 1e-9 {
+		t.Fatalf("Tokens() = %v, want 0.5 after clock passes reference", got)
+	}
+}
+
+func TestNewBucketRejectsBadConfig(t *testing.T) {
+	now := func() time.Time { return time.Unix(0, 0) }
+	bad := []struct {
+		c, r float64
+		n    func() time.Time
+	}{
+		{0, 1, now}, {-1, 1, now}, {math.NaN(), 1, now}, {math.Inf(1), 1, now},
+		{1, 0, now}, {1, math.Inf(1), now}, {1, 1, nil},
+	}
+	for i, tc := range bad {
+		if b, err := NewBucket(tc.c, tc.r, tc.n); b != nil || err != ErrInvalidConfig {
+			t.Errorf("case %d: got (%v, %v), want (nil, ErrInvalidConfig)", i, b, err)
+		}
+	}
+}

diff --git a/sched/plan_test.go b/sched/plan_test.go
new file mode 100644
