+++ b/sched/plan_test.go
@@ -0,0 +1,174 @@
+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"strings"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"doc":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"doc", "util"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanEmpty(t *testing.T) {
+	got, err := Plan(nil)
+	if err != nil || got == nil || len(got) != 0 {
+		t.Fatalf("Plan(nil) = %v, %v", got, err)
+	}
+}
+
+func TestPlanUnknownDepWinsOverCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"b": {"a"},
+		"a": {"b", "zz", "yy"},
+		"c": {"nope"},
+	})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "a" || ue.Dep != "yy" {
+		t.Fatalf("err = %v", err)
+	}
+	if ue.Error() != fmt.Sprintf("task %q depends on unknown task %q", "a", "yy") {
+		t.Fatalf("Error() = %q", ue.Error())
+	}
+}
+
+func TestPlanCanonicalCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"p": {"r", "q"},
+		"q": {"s"},
+		"s": {"p"},
+		"r": {"p"},
+	})
+	var ce *CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	if got := ce.Error(); got != "dependency cycle: p -> q -> s -> p" {
+		t.Fatalf("Error() = %q", got)
+	}
+	_, err = Plan(map[string][]string{"b": {"b"}})
+	if err == nil || err.Error() != "dependency cycle: b -> b" {
+		t.Fatalf("self-cycle err = %v", err)
+	}
+}
+
+func TestSimulateBasic(t *testing.T) {
+	s, err := Simulate(map[string]Task{
+		"a": {Duration: 3},
+		"b": {Duration: 2, Deps: []string{"a"}},
+		"c": {Duration: 5},
+	}, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Makespan != 5 {
+		t.Fatalf("Makespan = %d", s.Makespan)
+	}
+	if s.Slots["c"] != (Slot{0, 5, 0}) || s.Slots["a"] != (Slot{0, 3, 1}) || s.Slots["b"] != (Slot{3, 5, 1}) {
+		t.Fatalf("Slots = %v", s.Slots)
+	}
+	if want := []string{"a", "b"}; !reflect.DeepEqual(s.CriticalPath, want) {
+		t.Fatalf("CriticalPath = %v", s.CriticalPath)
+	}
+}
+
+func TestSimulateEmptyAndErrors(t *testing.T) {
+	s, err := Simulate(nil, 1)
+	if err != nil || s.Slots == nil || s.CriticalPath == nil || s.Makespan != 0 {
+		t.Fatalf("empty = %+v, %v", s, err)
+	}
+	if _, err := Simulate(nil, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err = Simulate(map[string]Task{"z": {Duration: 0}, "y": {Duration: -1}}, 1)
+	var de *InvalidDurationError
+	if !errors.As(err, &de) || de.Task != "y" {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestLargeGraphsWithinLimit(t *testing.T) {
+	const n = 200000
+	name := func(i int) string { return fmt.Sprintf("t%07d", i) }
+
+	// Long chain plus fan-in dependencies.
+	chain := make(map[string][]string, n)
+	tasks := make(map[string]Task, n)
+	for i := 0; i < n; i++ {
+		var deps []string
+		if i > 0 {
+			deps = append(deps, name(i-1))
+		}
+		if i > 5 {
+			deps = append(deps, name(i-3), name(i-5))
+		}
+		chain[name(i)] = deps
+		tasks[name(i)] = Task{Deps: deps, Duration: 1 + i%7, Priority: i % 3}
+	}
+	start := time.Now()
+	if _, err := Plan(chain); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := Simulate(tasks, 8); err != nil {
+		t.Fatal(err)
+	}
+	if d := time.Since(start); d > 4*time.Second {
+		t.Fatalf("took %v", d)
+	}
+
+	// Ring of 100000 tasks with a tail hanging off it.
+	ring := make(map[string][]string, n)
+	const r = 100000
+	for i := 0; i < r; i++ {
+		ring[name(i)] = []string{name((i + 1) % r)}
+	}
+	for i := r; i < n; i++ {
+		ring[name(i)] = []string{name(i - 1)}
+	}
+	start = time.Now()
+	_, err := Plan(ring)
+	var ce *CycleError
+	if !errors.As(err, &ce) || len(ce.Path) != r+1 || ce.Path[0] != name(0) {
+		t.Fatalf("ring err = %v", err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("ring took %v", d)
+	}
+
+	// Many 2-cycles fed by a chain.
+	pairs := make(map[string][]string, n)
+	for i := 0; i < 50000; i++ {
+		pairs[fmt.Sprintf("c%06d_a", i)] = []string{fmt.Sprintf("c%06d_b", i)}
+		pairs[fmt.Sprintf("c%06d_b", i)] = []string{fmt.Sprintf("c%06d_a", i)}
+	}
+	for i := 0; i < 100000; i++ {
+		deps := []string{fmt.Sprintf("c%06d_a", i%50000)}
+		if i > 0 {
+			deps = append(deps, fmt.Sprintf("chain%06d", i-1))
+		}
+		pairs[fmt.Sprintf("chain%06d", i)] = deps
+	}
+	start = time.Now()
+	_, err = Plan(pairs)
+	if !errors.As(err, &ce) || !strings.HasPrefix(ce.Error(), "dependency cycle: c000000_a -> c000000_b -> c000000_a") {
+		t.Fatalf("pairs err = %v", err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("pairs took %v", d)
+	}
+}

diff --git a/tests/arith.rs b/tests/arith.rs
new file mode 100644
index 0000000..5647e97
--- /dev/null
+++ b/tests/arith.rs
@@ -0,0 +1,114 @@
+use exprkit::{eval, EvalError};
+use std::collections::HashMap;
+
+fn run(s: &str) -> Result<f64, EvalError> {
+    eval(s, &HashMap::new())
+}
+
+fn with_x(s: &str, x: f64) -> Result<f64, EvalError> {
+    let mut vars = HashMap::new();
+    vars.insert("x".to_string(), x);
+    eval(s, &vars)
+}
+
+#[test]
+fn precedence_and_signs() {
+    assert_eq!(run("-2^2"), Ok(-4.0));
+    assert_eq!(run("(-2)^2"), Ok(4.0));
+    assert_eq!(run("2^-1"), Ok(0.5));
+    assert_eq!(run("2^3^2"), Ok(512.0));
+    assert_eq!(run("--3"), Ok(3.0));
+    assert_eq!(run("2--2"), Ok(4.0));
+    assert_eq!(run("7 % 4 % 2"), Ok(1.0));
+    assert_eq!(run("-7 % 3"), Ok(-1.0));
+    assert_eq!(run("7.5 % 2"), Ok(1.5));
+}
+
+#[test]
+fn implicit_multiplication() {
+    assert_eq!(with_x("2x", 5.0), Ok(10.0));
+    assert_eq!(with_x("2 x", 5.0), Ok(10.0));
+    assert_eq!(with_x("x x", 3.0), Ok(9.0));
+    assert_eq!(run("2(3+4)"), Ok(14.0));
+    assert_eq!(run("(1+2)(3+4)"), Ok(21.0));
+    assert_eq!(run("2(3)(4)"), Ok(24.0));
+    assert_eq!(run("3abs(-2)"), Ok(6.0));
+    assert_eq!(with_x("2x^2", 3.0), Ok(18.0));
+    assert_eq!(with_x("-2x", 3.0), Ok(-6.0));
+    assert_eq!(with_x("2^3x", 2.0), Ok(16.0));
+    assert_eq!(run("6/2(1+2)"), Ok(9.0));
+    assert_eq!(with_x("2x(3)", 3.0), Err(EvalError::UnknownFunc("x".into())));
+}
+
+#[test]
+fn numbers_and_identifiers() {
+    assert_eq!(run("007"), Ok(7.0));
+    assert_eq!(run("10.25"), Ok(10.25));
+    assert_eq!(run(".5"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("5."), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("X"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("1,2"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("2 3"), Err(EvalError::Parse { pos: 2 }));
+    assert_eq!(run("(2)3"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(with_x("x 2", 2.0), Err(EvalError::Parse { pos: 2 }));
+}
+
+#[test]
+fn parse_error_positions() {
+    assert_eq!(run(""), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("   "), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("1 + 2)"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(run("()"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("(1 + 2"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("1 +"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("max(1"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(run("min(1 2)"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("min(,1)"), Err(EvalError::Parse { pos: 4 }));
+    assert_eq!(run("min(1,)"), Err(EvalError::Parse { pos: 6 }));
+}
+
+#[test]
+fn functions_and_errors() {
+    assert_eq!(run("min()"), Err(EvalError::Arity { name: "min".into(), expected: "at least 1".into(), got: 0 }));
+    assert_eq!(run("min(3, 1, 2)"), Ok(1.0));
+    assert_eq!(run("max(3, 1, 2)"), Ok(3.0));
+    assert_eq!(run("abs()"), Err(EvalError::Arity { name: "abs".into(), expected: "1".into(), got: 0 }));
+    assert_eq!(run("sqrt(4, 1)"), Err(EvalError::Arity { name: "sqrt".into(), expected: "1".into(), got: 2 }));
+    assert_eq!(run("sqrt(-1)"), Err(EvalError::Domain("sqrt".into())));
+    assert_eq!(run("foo(1)"), Err(EvalError::UnknownFunc("foo".into())));
+    assert_eq!(run("1 / 0"), Err(EvalError::DivByZero));
+    assert_eq!(run("1 % -0.0"), Err(EvalError::DivByZero));
+    assert_eq!(run("y + 1"), Err(EvalError::UnknownVar("y".into())));
+    assert_eq!(run("1 + 2 )"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("y 1"), Err(EvalError::Parse { pos: 2 }));
+}
+
+#[test]
+fn parse_error_wins_over_eval_error() {
+    assert_eq!(run("1 / 0 2"), Err(EvalError::Parse { pos: 6 }));
+}
+
+#[test]
+fn deep_inputs_do_not_overflow() {
+    let n = 100_000;
+    let s = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(1.0));
+
+    let s = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(3.0));
+
+    let s = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    assert_eq!(run(&s), Ok(5.0));
+
+    let s = format!("{}3", "-".repeat(n));
+    assert_eq!(run(&s), Ok(3.0));
+
+    let s = format!("{}1", "1^".repeat(n));
+    assert_eq!(run(&s), Ok(1.0));
+
+    let s = vec!["1"; 200_000].join("+");
+    assert_eq!(run(&s), Ok(200_000.0));
+
+    let s = "(1)".repeat(n);
+    assert_eq!(run(&s), Ok(1.0));
+}

