+use intervalkit::intervals::{Bound, IntervalSet};
+use std::time::Instant;
+
+use Bound::{Closed as C, Open as O};
+
+#[test]
+fn empty_interval_rules() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(2));
+    s.insert(C(2), O(2));
+    s.insert(O(2), C(2));
+    s.insert(C(3), C(2));
+    assert!(s.is_empty());
+    assert!(s.ranges().is_empty());
+    s.insert(C(2), C(2));
+    assert!(!s.is_empty());
+    assert_eq!(s.ranges(), vec![(C(2), C(2))]);
+    let mut t = IntervalSet::new();
+    t.insert(O(2), C(3));
+    assert!(!t.is_empty());
+    assert!(t.contains(2.5));
+    assert!(!t.contains(2.0));
+}
