+    b.insert(O(3), O(5));
+    assert_eq!(b.ranges(), vec![(C(1), O(5))]);
+    assert_ne!(b.ranges(), vec![(C(1), C(5))]);
+
+    let mut c = IntervalSet::new();
+    c.insert(O(1), O(3));
+    c.insert(C(3), C(3));
+    assert_eq!(c.ranges(), vec![(O(1), C(3))]);
+
+    let mut d = IntervalSet::new();
+    d.insert(O(1), O(3));
+    d.insert(O(3), O(5));
+    assert_eq!(d.ranges(), vec![(O(1), O(3)), (O(3), O(5))]);
+
+    let mut e = IntervalSet::new();
+    e.insert(C(1), O(3));
+    e.insert(O(3), C(5));
+    assert_eq!(e.ranges(), vec![(C(1), O(3)), (O(3), C(5))]);
+    assert_ne!(e.ranges(), vec![(C(1), C(5))]);
+}
+
+#[test]
+fn single_point_form() {
+    let mut s = IntervalSet::new();
+    s.insert(C(7), C(7));
+    assert_eq!(s.ranges(), vec![(C(7), C(7))]);
+    assert_eq!(s.measure(), 0);
+    assert_ne!(s.ranges(), vec![(O(7), C(7))]);
+}
+
+#[test]
+fn remove_splits_intervals() {
+    let mut a = IntervalSet::new();
+    a.insert(C(1), C(5));
+    a.remove(C(2), C(2));
+    assert_eq!(a.ranges(), vec![(C(1), O(2)), (O(2), C(5))]);
+    assert!(!a.contains(2.0));
+    assert!(a.contains(1.5));
+
+    let mut b = IntervalSet::new();
+    b.insert(C(1), C(5));
+    b.remove(O(2), O(4));
+    assert_eq!(b.ranges(), vec![(C(1), C(2)), (C(4), C(5))]);
+    assert!(b.contains(2.0));
+    assert!(!b.contains(3.0));
+
+    let mut c = IntervalSet::new();
+    c.insert(C(1), C(5));
+    c.remove(C(3), C(9));
+    c.remove(C(7), C(7));
+    assert_eq!(c.ranges(), vec![(C(1), O(3))]);
+}
+
+#[test]
+fn contains_uses_real_membership() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(3));
+    assert!(s.contains(2.5));
+    assert!(!s.contains(2.0));
+    assert!(!s.contains(3.0));
+    assert!(!s.contains(1.9999));
+    let mut t = IntervalSet::new();
+    t.insert(C(2), C(3));
+    assert!(t.contains(2.0));
+    assert!(t.contains(3.0));
+    assert!(!t.contains(3.5));
+}
+
+#[test]
+fn measure_sums_lengths() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(3));
+    s.insert(O(3), C(5));
+    s.insert(C(10), C(10));
+    assert_eq!(s.measure(), 4);
+    assert_ne!(s.measure(), 6);
+
+    let mut e = IntervalSet::new();
+    e.insert(C(i64::MIN), C(i64::MAX));
+    assert_eq!(e.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert_eq!(e.measure(), 18446744073709551615i128);
+}
+
+#[test]
+fn complement_within_window() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), O(4));
+    s.insert(O(6), C(8));
+    assert_eq!(
+        s.complement(C(0), C(10)),
+        vec![(C(0), O(2)), (C(4), C(6)), (O(8), C(10))]
+    );
+    assert!(s.complement(C(5), O(5)).is_empty());
+    assert!(s.complement(C(2), O(4)).is_empty());
+    let mut full = IntervalSet::new();
+    full.insert(C(0), C(10));
+    assert!(full.complement(C(1), C(9)).is_empty());
+    assert_ne!(full.complement(C(1), C(9)), vec![(C(1), C(9))]);
+}
+
+#[test]
+fn display_format() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(3));
+    s.insert(O(4), C(5));
+    s.insert(C(7), C(7));
+    assert_eq!(format!("{}", s), "{[1,3), (4,5], [7,7]}");
+
+    let mut n = IntervalSet::new();
+    n.insert(O(-3), C(0));
+    assert_eq!(format!("{}", n), "{(-3,0]}");
+    assert_ne!(format!("{}", n), "{(-3, 0]}");
+
+    assert_eq!(format!("{}", IntervalSet::new()), "{}");
+}
+
+#[test]
+fn extreme_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    assert!(s.contains(i64::MAX as f64));
+    assert!(s.contains(i64::MIN as f64));
+    assert_eq!(s.ranges(), vec![(C(i64::MIN), C(i64::MAX))]);
+    s.remove(C(i64::MIN), O(i64::MAX));
+    assert_eq!(s.ranges(), vec![(C(i64::MAX), C(i64::MAX))]);
+    assert_eq!(s.complement(C(i64::MIN), C(i64::MAX)), vec![(C(i64::MIN), O(i64::MAX))]);
+    s.remove(C(i64::MIN), C(i64::MAX));
+    assert!(s.is_empty());
+    assert_eq!(s.measure(), 0);
+}
+
+struct Lcg(u64);
+
+impl Lcg {
+    fn next(&mut self) -> u64 {
+        self.0 = self
+            .0
+            .wrapping_mul(6364136223846793005)
+            .wrapping_add(1442695040888963407);
+        self.0 >> 11
+    }
+    fn range(&mut self, lo: i64, hi: i64) -> i64 {
+        lo + (self.next() % ((hi - lo + 1) as u64)) as i64
+    }
+}
+
+#[test]
+fn large_sweep_finishes_quickly() {
+    let mut rng = Lcg(12345);
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300000i64 {
+        let base = 1_000_000_000 - i * 3333;
+        let lo = base + rng.range(-1000, 1000);
+        let len = rng.range(0, 1000);
+        let hi = lo + len;
+        if i % 2 == 0 {
+            s.insert(C(lo), C(hi));
+        } else {
+            s.remove(C(lo), C(hi));
+        }
+        let x = (rng.next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    let elapsed = start.elapsed();
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+    assert!(s.measure() >= 0);
+}

