+    assert_eq!(to_roman(0), Err(RomanError::OutOfRange));
+    assert_eq!(to_roman(4000), Err(RomanError::OutOfRange));
+}
+
+#[test]
+fn rejects_junk_and_reports_errors_in_order() {
+    assert_eq!(from_roman(""), Err(RomanError::Empty));
+    assert_eq!(from_roman("xiv"), Err(RomanError::InvalidChar('x')));
+    assert_eq!(from_roman("IV V"), Err(RomanError::InvalidChar(' ')));
+    assert_eq!(from_roman("IIII"), Err(RomanError::NonCanonical));
+    assert_eq!(from_roman("IC"), Err(RomanError::NonCanonical));
+    assert_eq!(from_roman("VX"), Err(RomanError::NonCanonical));
+    assert_eq!(from_roman("MMMM"), Err(RomanError::NonCanonical));
