+    assert_eq!(from_roman("XIX"), Ok(19));
+}
+
+#[test]
+fn round_trips_every_value() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s), Ok(n), "numeral {s}");
+    }
