+    let r = Shape::Rect { w: 3.0, h: 4.0 };
+    assert!(close(r.area().unwrap(), 12.0));
+    assert!(close(r.perimeter().unwrap(), 14.0));
+    let t = Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 };
