+    assert_eq!(Shape::Circle { r: -1.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: -1.0, h: 2.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: 1.0, h: -2.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 5.0 }.perimeter(), Err(ShapeError::InvalidTriangle));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 5.0 }.area(), Err(ShapeError::InvalidTriangle));
+    assert_eq!(Shape::Triangle { a: -1.0, b: 1.0, c: 5.0 }.area(), Err(ShapeError::NegativeDimension));
