+
+#[test]
+fn free_functions_match_shape_methods_on_success() {
+    assert!(close(area("Square", &[2.0]).unwrap(), 4.0));
+    assert!(close(area("circle", &[1.0]).unwrap(), PI));
+    assert!(close(perimeter("circle", &[1.0]).unwrap(), 2.0 * PI));
+    assert!(close(perimeter("RECTANGLE", &[2.0, 3.0]).unwrap(), 10.0));
