+
+#[test]
+fn free_functions_return_exact_error_strings() {
+    assert_eq!(area("hex", &[1.0]), Err("unknown shape kind: hex".to_string()));
+    assert_eq!(perimeter("Hex", &[1.0]), Err("unknown shape kind: Hex".to_string()));
+    assert_eq!(area("circle", &[1.0, 2.0]), Err("expected 1 params, got 2".to_string()));
+    assert_eq!(perimeter("rect", &[-1.0, 1.0]), Err("dimensions must be non-negative".to_string()));
+    assert_eq!(area("rect", &[-1.0, 1.0]), Err("dimensions must be non-negative".to_string()));
+    assert_eq!(perimeter("triangle", &[1.0, 1.0, 5.0]), Err("sides do not form a triangle".to_string()));
+    assert_eq!(area("triangle", &[1.0, 1.0, 5.0]), Err("sides do not form a triangle".to_string()));
