+
+#[test]
+fn mean_ignores_nan_and_is_none_when_empty() {
+    assert!(close(mean(&[1.0, f64::NAN, 3.0]), 2.0));
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN]), None);
+    assert!(mean(&[1.0, f64::NAN]).map_or(false, |m| !m.is_nan()));
+}
+
+#[test]
+fn median_is_percentile_50_and_ignores_nan() {
