+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN, f64::NAN]), None);
+    assert_ne!(median(&[1.0, 2.0, 3.0, 4.0]), Some(2.0));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation() {
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), 3.7));
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 0.0), 1.0));
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 100.0), 4.0));
+    assert!(!close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), 3.0));
