+
+#[test]
+fn percentile_is_order_independent_and_keeps_input() {
+    let v = vec![3.0, 1.0, 4.0, 2.0];
+    assert!(close(percentile(&v, 50.0), 2.5));
+    assert_eq!(v, vec![3.0, 1.0, 4.0, 2.0]);
+    assert!(close(percentile(&[4.0, 2.0, 1.0, 3.0], 50.0), 2.5));
+}
+
+#[test]
+fn percentile_rejects_nan_and_out_of_range_p() {
+    let v = [1.0, 2.0, 3.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+    assert!(close(percentile(&v, 100.0), 3.0));
