+#[test]
+fn percentile_is_none_when_no_non_nan_values() {
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[f64::NAN], 50.0), None);
+    assert!(close(percentile(&[f64::NAN, 7.0], 50.0), 7.0));
+}

