+import { expect, test } from "bun:test";
+import { cartTotal, InvalidDiscountError } from "../src/cart";
+import { checkoutSummary } from "../src/checkout";
+
+const small = [{ sku: "mug", priceCents: 1200, qty: 2 }]; // 2400, ship 499
+const big = [{ sku: "lamp", priceCents: 6000, qty: 1 }]; // 6000, free ship
+
+test("no code behaves like today", () => {
+  expect(cartTotal(small, undefined)).toBe(2899);
+  expect(cartTotal(small, "")).toBe(2899);
+  expect(cartTotal(small, "   ")).toBe(2899);
+});
+
+test("SAVE10 takes 10% off the subtotal", () => {
+  expect(cartTotal(small, "SAVE10")).toBe(2400 - 240 + 499);
+  expect(cartTotal(big, "SAVE10")).toBe(6000 - 600);
+});
+
+test("SAVE10 rounds to the nearest cent", () => {
+  const odd = [{ sku: "pen", priceCents: 1005, qty: 1 }]; // 10% = 100.5 -> 101
+  expect(cartTotal(odd, "SAVE10")).toBe(1005 - 101 + 499);
+});
+
+test("FLAT5 takes 500 cents off, never below zero", () => {
+  expect(cartTotal(small, "FLAT5")).toBe(2400 - 500 + 499);
+  const tiny = [{ sku: "gum", priceCents: 300, qty: 1 }];
+  expect(cartTotal(tiny, "FLAT5")).toBe(0 + 499);
+});
+
+test("FREESHIP waives shipping", () => {
+  expect(cartTotal(small, "FREESHIP")).toBe(2400);
+});
+
+test("codes are case-insensitive and ignore surrounding spaces", () => {
+  expect(cartTotal(small, "  save10 ")).toBe(cartTotal(small, "SAVE10"));
+  expect(cartTotal(small, "FreeShip")).toBe(2400);
+});
+
+test("free shipping eligibility uses the pre-discount subtotal", () => {
+  // 5200 subtotal qualifies for free shipping; SAVE10 drops it to 4680,
+  // but shipping still stays free.
+  const edge = [{ sku: "desk", priceCents: 5200, qty: 1 }];
+  expect(cartTotal(edge, "SAVE10")).toBe(5200 - 520);
+});
+
+test("unknown code throws InvalidDiscountError", () => {
+  expect(() => cartTotal(small, "NOPE")).toThrow(InvalidDiscountError);
+});
+
+test("checkoutSummary passes the code through", () => {
+  expect(checkoutSummary(small, "FREESHIP")).toBe("Total: $24.00");
+  expect(checkoutSummary(small)).toBe("Total: $28.99");
+});

