diff --git a/test/cron.test.ts b/test/cron.test.ts
new file mode 100644
index 0000000..e89734e
--- /dev/null
+++ b/test/cron.test.ts
@@ -0,0 +1,101 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const at = (iso: string) => new Date(iso);
+const iso = (d: Date) => d.toISOString();
+
+test("steps and lists in minute field", () => {
+  expect(iso(nextRun("*/15 * * * *", at("2024-01-01T00:07:30Z")))).toBe("2024-01-01T00:15:00.000Z");
+  expect(iso(nextRun("10-50/20 * * * *", at("2024-01-01T00:10:00Z")))).toBe("2024-01-01T00:30:00.000Z");
+  expect(iso(nextRun("5,40 * * * *", at("2024-01-01T00:06:00Z")))).toBe("2024-01-01T00:40:00.000Z");
+});
+
+test("names are case-insensitive in month and day-of-week", () => {
+  expect(iso(nextRun("0 0 1 jan,JUL *", at("2024-02-01T00:00:00Z")))).toBe("2024-07-01T00:00:00.000Z");
+  expect(iso(nextRun("0 9 * * mon-fri", at("2024-01-06T10:00:00Z")))).toBe("2024-01-08T09:00:00.000Z");
+});
+
+test("day-of-month OR day-of-week when both restricted", () => {
+  expect(iso(nextRun("0 0 L * 1", at("2024-02-01T00:00:00Z")))).toBe("2024-02-05T00:00:00.000Z");
+});
+
+test("AND semantics when one day field is *", () => {
+  expect(iso(nextRun("0 0 * 2 5L", at("2024-01-01T00:00:00Z")))).toBe("2024-02-23T00:00:00.000Z");
+});
+
+test("nth and last weekday specials", () => {
+  expect(iso(nextRun("0 0 * * 5#3", at("2024-01-01T00:00:00Z")))).toBe("2024-01-19T00:00:00.000Z");
+  expect(iso(nextRun("0 0 * * FRI#3", at("2024-01-01T00:00:00Z")))).toBe("2024-01-19T00:00:00.000Z");
+  expect(iso(nextRun("0 0 LW 2 *", at("2024-01-01T00:00:00Z")))).toBe("2024-02-29T00:00:00.000Z");
+});
+
+test("nW: Saturday moves to Friday, Sunday moves to Monday", () => {
+  // 2024-06-15 is a Saturday -> Friday 14th
+  expect(iso(nextRun("0 0 15W 6 *", at("2024-01-01T00:00:00Z")))).toBe("2024-06-14T00:00:00.000Z");
+  // 2024-09-01 is a Sunday -> Monday 2nd
+  expect(iso(nextRun("0 0 1W 9 *", at("2024-01-01T00:00:00Z")))).toBe("2024-09-02T00:00:00.000Z");
+});
+
+test("aliases", () => {
+  expect(iso(nextRun("@daily", at("2024-01-01T10:20:00Z")))).toBe("2024-01-02T00:00:00.000Z");
+  expect(iso(nextRun("@HOURLY", at("2024-01-01T10:20:00Z")))).toBe("2024-01-01T11:00:00.000Z");
+});
+
+test("result is a new Date and from is not modified", () => {
+  const from = at("2024-01-01T00:00:45.123Z");
+  const out = nextRun("* * * * *", from);
+  expect(iso(out)).toBe("2024-01-01T00:01:00.000Z");
+  expect(iso(from)).toBe("2024-01-01T00:00:45.123Z");
+});
+
+test("Feb 29 schedules skip to the next leap year", () => {
+  expect(iso(nextRun("0 0 29 2 *", at("2024-03-01T00:00:00Z")))).toBe("2028-02-29T00:00:00.000Z");
+});
+
+test("throws when no match exists within 5 years", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("invalid expressions throw CronError", () => {
+  const invalid = [
+    "* * * *",
+    "60 * * * *",
+    "5/15 * * * *",
+    "*/0 * * * *",
+    "5-1 * * * *",
+    "1,,2 * * * *",
+    "* * * jan-foo *",
+    "* * * * 8#1",
+    "* * * * 5#0",
+    "* * * * 5#6",
+    "* * * * 1W",
+    "* * * * L",
+    "0 0 W * *",
+    "0 0 1-5W * *",
+    "0 0 L/2 * *",
+    "0 0 0W * *",
+    "0 0 32W * *",
+    "0 0 * * 5L/2",
+    "0 0 * * dW",
+    "* * * * JAN",
+    "@foo * * * *",
+    "@daily 1",
+  ];
+  for (const expr of invalid) {
+    expect(() => nextRun(expr, at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+  }
+});
+
+test("3000 calls over varied schedules run quickly", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const start = performance.now();
+  for (let i = 0; i < 3000; i++) {
+    const from = new Date(Date.UTC(2000 + (i % 100), (i * 7) % 12, 1 + ((i * 13) % 28)));
+    try {
+      nextRun(schedules[i % schedules.length], from);
+    } catch (err) {
+      expect(err).toBeInstanceOf(CronError);
+    }
+  }
+  expect(performance.now() - start).toBeLessThan(2000);
+});

