+++ b/test/paginate-fix.test.ts
@@ -0,0 +1,46 @@
+import { expect, test } from "bun:test";
+import { paginate } from "../src/paginate";
+import { listUsers } from "../src/users";
+
+test("keeps the last item of a full page", () => {
+  const p = paginate([1, 2, 3, 4], 1, 2);
+  expect(p.items).toEqual([1, 2]);
+  expect(p.hasNext).toBe(true);
+});
+
+test("counts a final partial page in totalPages", () => {
+  const p = paginate([1, 2, 3, 4, 5], 1, 2);
+  expect(p.totalPages).toBe(3);
+  expect(p.hasNext).toBe(true);
+});
+
+test("last partial page has the remaining items and no next", () => {
+  const p = paginate([1, 2, 3, 4, 5], 3, 2);
+  expect(p.items).toEqual([5]);
+  expect(p.hasNext).toBe(false);
+});
+
+test("page past the end returns empty items", () => {
+  const p = paginate([1, 2, 3], 5, 2);
+  expect(p.items).toEqual([]);
+  expect(p.hasNext).toBe(false);
+});
+
+test("empty input has 0 total pages", () => {
+  const p = paginate([], 1, 10);
+  expect(p.totalPages).toBe(0);
+  expect(p.items).toEqual([]);
+  expect(p.hasNext).toBe(false);
+});
+
+test("listUsers paginates sorted users without dropping items", () => {
+  const users = [
+    { id: 3, name: "c" },
+    { id: 1, name: "a" },
+    { id: 2, name: "b" },
+  ];
+  const p = listUsers(users, 1, 2);
+  expect(p.items.map((u) => u.id)).toEqual([1, 2]);
+  expect(p.totalPages).toBe(2);
+  expect(p.hasNext).toBe(true);
+});

